package org.jlinalg.cli;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.nio.file.StandardOpenOption;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.jlinalg.assembly.HifiasmParentalKmers;
import static org.jlinalg.cli.Monocle3WorkflowRequest.*;

/** Original full-mode reference controls only; not the unfinished public assembly adapter. */
public final class HifiasmAssemblyControl {
    private HifiasmAssemblyControl(){ }
    public static void main(String[] args)throws Exception{
        require(args.length==2,"Require control request and NEW output");Path request=Path.of(args[0]).toAbsolutePath().normalize(),out=Path.of(args[1]).toAbsolutePath().normalize();require(!Files.exists(out)&&out.getParent().equals(out.getParent().toRealPath()),"Require NEW output under canonical parent");Files.createDirectory(out);var state=new LinkedHashMap<String,Object>();state.put("status","FAIL2_ORIGINAL_HIFIASM_CONTROL_BATCH");state.put("analysis_admitted",false);state.put("full_adapter_admitted",false);state.put("implementation_credit",false);state.put("started_at",Instant.now().toString());var reports=new ArrayList<Object>();int exit=2;
        try{
            var root=GseapyExecutionRuntime.read(request,16777216);require(text(root.get("mode")).equals("ORIGINAL_ASSEMBLY_CONTROL_ONLY"),"This driver admits no user assembly");Files.write(out.resolve("request.original.json"),NextflowFiles.bytes(request,16777216),StandardOpenOption.CREATE_NEW);Path buildRoot=Path.of(text(root.get("reference_builds")));var builds=GseapyExecutionRuntime.read(buildRoot.resolve("COMPLETED.json"),16777216);require(text(builds.get("status")).equals("passed-requested-original-hifiasm-source-builds-only"),"Require complete successful original source builds");var versions=object(builds.get("editions"));Path inputs=Files.createDirectory(out.resolve("inputs"));var captured=new LinkedHashMap<String,Path>();var pins=new LinkedHashMap<Path,NextflowFiles.Pin>();
            for(var e:object(root.get("inputs")).entrySet()){var desc=object(e.getValue());Path source=Path.of(text(desc.get("path")));require(Files.isRegularFile(source,LinkOption.NOFOLLOW_LINKS)&&source.equals(source.toRealPath()),"Original input must be canonical and regular");var expected=NextflowFiles.fingerprint(desc,268435456);require(expected.equals(NextflowFiles.pin(source,268435456,()->{})),"Original synthetic input changed");Path copy=inputs.resolve(e.getKey()+".fa");Files.copy(source,copy);require(expected.equals(NextflowFiles.pin(copy,268435456,()->{})),"Copied source input differs");captured.put(e.getKey(),copy);pins.put(copy,expected);pins.put(source,expected);}
            Path parents=Files.createDirectory(out.resolve("parents"));var parentPaths=new ArrayList<Path>();int parentIndex=0;
            for(Object raw:list(root.get("parental_sequences"))){byte[] sequence=text(raw).getBytes(StandardCharsets.US_ASCII);require(sequence.length<=2000000&&text(raw).matches("[ACGT]+"),"Declare controlled unambiguous parental sequence");var copies=new ArrayList<byte[]>();for(int i=0;i<6;i++)copies.add(sequence);var counts=HifiasmParentalKmers.count(copies,31,10,12000000,4000000);Path file=parents.resolve("parent"+(++parentIndex)+".yak");try(var stream=new java.io.BufferedOutputStream(Files.newOutputStream(file,StandardOpenOption.CREATE_NEW),65536)){HifiasmParentalKmers.write(counts,stream);}parentPaths.add(file);pins.put(file,NextflowFiles.pin(file,67108864,()->{}));}
            require(parentPaths.size()==2,"Require two declared synthetic parental families");NextflowFiles.writeJson(parents.resolve("PROVENANCE.json"),Map.of("producer","Native HifiasmParentalKmers direct counting, six copies per synthetic parental genome, k31,prefix10, no Bloom filter","yak_runtime_used",false,"paper_parental_database_reproduced",false));
            var binaries=new LinkedHashMap<String,Path>();var probed=new java.util.HashSet<String>();var environment=Map.of("PATH","/usr/bin:/bin","LANG","C","LC_ALL","C","TZ","UTC","HOME",out.toString(),"TMPDIR",out.toString(),"OMP_NUM_THREADS","1");RsemProcess.Check check=()->{for(var e:pins.entrySet())require(e.getValue().equals(NextflowFiles.pin(e.getKey(),268435456,()->{})),"Bound original input/binary changed during controls");};
            for(Object value:list(root.get("cases"))){var spec=object(value);String id=text(spec.get("id")),edition=text(spec.get("edition")),mode=text(spec.get("assembly_mode"));require(id.matches("[A-Za-z0-9._-]+")&&versions.containsKey(edition)&&Set.of("hifi","trio","hic","hifi-ul","trio-ul","hic-ul","ont").contains(mode),"Invalid declared original control");Path home=Files.createDirectory(out.resolve(id));
                if(!binaries.containsKey(edition)){var receipt=object(object(versions.get(edition)).get("receipt"));require(text(receipt.get("status")).equals("PASS_ORIGINAL_HIFIASM_SOURCE_COMPILATION_ONLY")&&Boolean.TRUE.equals(receipt.get("original_source_members_unchanged")),"Original compilation not admitted");var binaryRecord=object(receipt.get("binary"));Path binary=Path.of(text(binaryRecord.get("path")));var expected=NextflowFiles.fingerprint(binaryRecord,1073741824);require(expected.equals(NextflowFiles.pin(binary,1073741824,()->{})),"Original compiled binary changed");pins.put(binary,expected);binaries.put(edition,binary);}
                Path binary=binaries.get(edition);if(probed.add(edition))HifiasmVersionProbe.probe(binary,edition,environment,home.resolve("version"),check);
                if(mode.endsWith("-ul"))require(List.of("0.19.5-r587","0.19.5-r592","0.22.0-r689").contains(edition),"UL mode not declared for this source edition");if(mode.equals("ont"))require(edition.equals("0.22.0-r689"),"ONT-only mode requires declared0.22.0 source");Path assembly=Files.createDirectory(home.resolve("assembly"));var command=new ArrayList<String>(List.of(binary.toString(),"-o",assembly.resolve("asm").toString(),"-t","1","-f0","-i"));
                if(mode.startsWith("trio"))command.addAll(List.of("-1",parentPaths.get(0).toString(),"-2",parentPaths.get(1).toString()));if(mode.startsWith("hic"))command.addAll(List.of("--h1",captured.get("hic1").toString(),"--h2",captured.get("hic2").toString()));if(mode.endsWith("-ul"))command.addAll(List.of("--ul",captured.get("ul").toString()));if(mode.equals("ont"))command.add("--ont");if(spec.get("purge_level")!=null)command.addAll(List.of("-l",Long.toString(integer(spec.get("purge_level"),0,3))));if(Boolean.TRUE.equals(spec.get("disable_post_join")))command.add("-u");command.add(captured.get(mode.equals("ont")?"ont":"hifi").toString());
                System.out.println("Original assembly "+id);var limits=new RsemProcess.Limits(600000,8589934592L,600,1073741824,1024,2147483648L,4096,32,256,6442450944L,100);var process=RsemProcess.executeOwned(command,environment,home.resolve("process"),limits,check,()->{},List.of(assembly));long gfaFiles=0,segments=0,sequenceBases=0;var files=new LinkedHashMap<String,Object>();
                try(var paths=Files.walk(assembly)){for(Path file:paths.filter(Files::isRegularFile).sorted().toList()){files.put(assembly.relativize(file).toString(),GseapyExecutionRuntime.pinObject(NextflowFiles.pin(file,1073741824,()->{})));if(file.getFileName().toString().endsWith(".gfa")){gfaFiles++;try(var lines=Files.newBufferedReader(file)){for(String line;(line=lines.readLine())!=null;)if(line.startsWith("S\t")){segments++;String[] fields=line.split("\t",-1);require(fields.length>=3,"Original segment row incomplete");if(!fields[2].equals("*"))sequenceBases+=fields[2].length();}}}}}
                require(gfaFiles>0&&segments>0&&sequenceBases>0&&process.ownedLiveAfterCleanup().isEmpty(),"Original control produced no complete sequence-bearing graph family");NextflowFiles.writeJson(home.resolve("original-output-files.json"),files);reports.add(Map.of("id",id,"edition",edition,"mode",mode,"command",command,"gfa_files",gfaFiles,"segment_rows",segments,"sequence_bases_across_all_graph_views",sequenceBases,"original_exit_code",process.exitCode(),"analysis_admitted",false));NextflowFiles.writeJson(out.resolve("earlier-complete-cases-provisional-"+reports.size()+".json"),reports);
            }
            check.verify();state.put("status","PASS_COMPLETE_ORIGINAL_HIFIASM_CONTROL_BATCH_ONLY");state.put("cases",reports);state.put("source_namespaces_patched",false);state.put("analysis_installed_software",false);state.put("yak_runtime_used",false);exit=0;
        }catch(Exception failed){state.put("error",failed.toString());state.put("earlier_complete_cases_are_provisional",reports);failed.printStackTrace(System.err);}
        finally{state.put("finished_at",Instant.now().toString());NextflowFiles.writeJson(out.resolve("COMPLETED.json"),state);Files.writeString(out.resolve("WARNINGS.md"),"# "+state.get("status")+"\n\nOriginal controlled assembly execution only. No user assembly, tool-level integration or paper reproduction is admitted. All earlier cases remain provisional if a later case fails. Full host/library binding, strict source/input policies, native complete GFA/corrected-read/FASTA audits and production adapter remain unfinished. Original graphs may be partially phased, empty per haplotype, nonconvergent or contain source diagnostics: inspect every original process log and retain all files. Bloom filtering is explicitly disabled (-f0) for these bounded synthetic controls; this is not paper-default equivalence. Native parent counting uses no Yak runtime and does not reproduce its Bloom-filter admission. Never refresh old scientific hashes.\n");}System.exit(exit);
    }
}
